-- Marketing Attribution System SQL Export
-- Generated from the baseline database

BEGIN TRANSACTION;
CREATE TABLE attribution_results (
            attribution_id TEXT PRIMARY KEY,
            opportunity_id TEXT NOT NULL,
            campaign_id TEXT NOT NULL,
            attribution_model TEXT NOT NULL,
            attribution_credit REAL NOT NULL
                CHECK (attribution_credit >= 0 AND attribution_credit <= 1),
            attributed_revenue REAL NOT NULL
                CHECK (attributed_revenue >= 0),
            attribution_date TEXT NOT NULL,
            FOREIGN KEY (opportunity_id)
                REFERENCES opportunities(opportunity_id),
            FOREIGN KEY (campaign_id)
                REFERENCES campaigns(campaign_id)
        );
CREATE TABLE audiences (
            audience_id TEXT PRIMARY KEY,
            audience_name TEXT NOT NULL,
            description TEXT
        );
CREATE TABLE campaign_audiences (
            campaign_id TEXT NOT NULL,
            audience_id TEXT NOT NULL,
            PRIMARY KEY (campaign_id, audience_id),
            FOREIGN KEY (campaign_id)
                REFERENCES campaigns(campaign_id),
            FOREIGN KEY (audience_id)
                REFERENCES audiences(audience_id)
        );
CREATE TABLE campaigns (
            campaign_id TEXT PRIMARY KEY,
            campaign_name TEXT NOT NULL,
            channel_id TEXT NOT NULL,
            budget REAL NOT NULL CHECK (budget >= 0),
            currency TEXT NOT NULL,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            status TEXT NOT NULL,
            FOREIGN KEY (channel_id)
                REFERENCES channels(channel_id),
            CHECK (end_date >= start_date)
        );
CREATE TABLE channels (
            channel_id TEXT PRIMARY KEY,
            channel_name TEXT NOT NULL UNIQUE
        );
CREATE TABLE contacts (
            contact_id TEXT PRIMARY KEY,
            contact_name TEXT NOT NULL,
            email TEXT UNIQUE,
            created_at TEXT NOT NULL
        );
CREATE TABLE cost_records (
            cost_id TEXT PRIMARY KEY,
            campaign_id TEXT NOT NULL,
            cost_amount REAL NOT NULL CHECK (cost_amount >= 0),
            currency TEXT NOT NULL,
            cost_date TEXT NOT NULL,
            FOREIGN KEY (campaign_id)
                REFERENCES campaigns(campaign_id)
        );
CREATE TABLE creatives (
            creative_id TEXT PRIMARY KEY,
            campaign_id TEXT NOT NULL,
            creative_name TEXT NOT NULL,
            creative_type TEXT NOT NULL,
            FOREIGN KEY (campaign_id)
                REFERENCES campaigns(campaign_id)
        );
CREATE TABLE leads (
            lead_id TEXT PRIMARY KEY,
            contact_id TEXT NOT NULL,
            session_id TEXT,
            created_at TEXT NOT NULL,
            status TEXT NOT NULL,
            FOREIGN KEY (contact_id)
                REFERENCES contacts(contact_id),
            FOREIGN KEY (session_id)
                REFERENCES web_sessions(session_id)
        );
CREATE TABLE opportunities (
            opportunity_id TEXT PRIMARY KEY,
            lead_id TEXT NOT NULL,
            contact_id TEXT NOT NULL,
            created_at TEXT NOT NULL,
            closed_at TEXT,
            status TEXT NOT NULL,
            FOREIGN KEY (lead_id)
                REFERENCES leads(lead_id),
            FOREIGN KEY (contact_id)
                REFERENCES contacts(contact_id)
        );
CREATE TABLE orders (
            order_id TEXT PRIMARY KEY,
            opportunity_id TEXT NOT NULL,
            revenue REAL NOT NULL CHECK (revenue >= 0),
            currency TEXT NOT NULL,
            order_date TEXT NOT NULL,
            FOREIGN KEY (opportunity_id)
                REFERENCES opportunities(opportunity_id)
        );
CREATE TABLE touchpoints (
            touchpoint_id TEXT PRIMARY KEY,
            contact_id TEXT NOT NULL,
            campaign_id TEXT NOT NULL,
            channel_id TEXT NOT NULL,
            creative_id TEXT,
            touchpoint_time TEXT NOT NULL,
            touch_type TEXT NOT NULL,
            FOREIGN KEY (contact_id)
                REFERENCES contacts(contact_id),
            FOREIGN KEY (campaign_id)
                REFERENCES campaigns(campaign_id),
            FOREIGN KEY (channel_id)
                REFERENCES channels(channel_id),
            FOREIGN KEY (creative_id)
                REFERENCES creatives(creative_id)
        );
CREATE TABLE web_sessions (
            session_id TEXT PRIMARY KEY,
            contact_id TEXT,
            session_time TEXT NOT NULL,
            source TEXT,
            anonymous INTEGER NOT NULL DEFAULT 0,
            FOREIGN KEY (contact_id)
                REFERENCES contacts(contact_id)
        );
COMMIT;
